			  set sqlStr = "INSERT into IHC_ITF_ITFCOMMON_X12.WorkFlow " _
			  " (InterchangeReceiverID, InterchangeSenderID, TransactionType, WorkStatus, ErrorType, Error, AssignedUser, CreateDtTm,  OrigX12Id) " _
			  " values (?,?,?,?,?,?,?,?,?)"
			  #dim rset As %SQL.StatementResult
