set ConfigName = "AutoIsaGs" set ctrlVerNum = "00401" set lnkObj = ##class(IHC.ERP.TPManage.TradeLink).%OpenId(lnkNum) // WRITE !, lnkObj.NAME set transSubType = ""
if ('$IsObject(lnkObj)) { $$$LOGERROR("Link not found: " _ lnkNum) QUIT $$$ERROR($$$EnsErrGeneral , "Link not found: " _ lnkNum) }
