set isaCtrlNum = "0" _ ctrlNum FOR i=$L(isaCtrlNum )+1:1:9 { set isaCtrlNum = "0" _ isaCtrlNum }
set isaSender = lnkObj.IsaSenderId.TPID FOR i=$L(isaSender )+1:1:15 { set isaSender = isaSender _ " " }
set isaReceiver = lnkObj.IsaReceiverId.TPID FOR i=$L(isaReceiver )+1:1:15 { set isaReceiver = isaReceiver _ " " }
set functionalGroupHeader = $CASE(lnkObj.TransactionType.Name, "810":"IN","850":"PO","852": "PD", "867": "PT",:"UN")
set target.Separators = $SELECT($L(lnkObj.Separators) = 3:sepStr, 1:"|~^")
set target.DocType = "ERP_4010:Interchange:Group:" _ lnkObj.TransactionType
// Interchange Control Header (ISA) values Do target.SetValueAt("00","ISA:AuthorizationInformationQual","set","") Do target.SetValueAt(" ", "ISA:AuthorizationInformation","set","") Do target.SetValueAt(" ", "ISA:SecurityInformation","set","") Do target.SetValueAt("00","ISA:SecurityInformationQualifier","set","") Do target.SetValueAt(lnkObj.IsaSenderId.TPFK.InterchangeIdQualifier,"ISA:InterchangeIDQualifier","set","") Do target.SetValueAt(isaSender,"ISA:InterchangeSenderID","set","") Do target.SetValueAt(lnkObj.IsaReceiverId.TPFK.InterchangeIdQualifier,"ISA:InterchangeIDQualifier2","set","") Do target.SetValueAt(isaReceiver,"ISA:InterchangeReceiverID","set","") Do target.SetValueAt($E(curDTM,3,8),"ISA:InterchangeDate","set","") Do target.SetValueAt($E($REPLACE(curDTM,":",""),10,13),"ISA:InterchangeTime","set","") Do target.SetValueAt(ctrlVerNum,"ISA:InterchangeControlVersionNum","set","") Do target.SetValueAt(isaCtrlNum,"ISA:InterchangeControlNumber","set","") Do target.SetValueAt("0","ISA:AcknowledgmentRequested","set","") Do target.SetValueAt("P","ISA:UsageIndicator","set","") Do target.SetValueAt("U","ISA:InterchangeControlStandardsI","set","")
Do target.SetValueAt("1","IEA:NumberofIncludedFunctionalGr","set","") Do target.SetValueAt(isaCtrlNum,"IEA:InterchangeControlNumber","set","")
// New Functional Group
Set target.FunctionalGroups(1)=##class(Ens.X12.FunctionSet).X12NewFunctionalGroup(target,"Group") Do target.FunctionalGroups(1).SetValueAt(functionalGroupHeader,"GS:FunctionalIdentifierCode", "set","") Do target.FunctionalGroups(1).SetValueAt(lnkObj.GsSenderId.TPID,"GS:ApplicationSendersCode","set","") Do target.FunctionalGroups(1).SetValueAt(lnkObj.GsReceiverId.TPID,"GS:ApplicationReceiversCode","set","") Do target.FunctionalGroups(1).SetValueAt($E(curDTM,1,8),"GS:Date","set","") Do target.FunctionalGroups(1).SetValueAt($E($REPLACE(curDTM,":",""),10,13),"GS:Time","set","")
Do target.FunctionalGroups(1).SetValueAt(ctrlNum,"GS:GroupControlNumber", "set","") Do target.FunctionalGroups(1).SetValueAt(ctrlNum,"GE:GroupControlNumber", "set","")
Do target.FunctionalGroups(1).SetValueAt("X","GS:ResponsibleAgencyCode", "set","") Do target.FunctionalGroups(1).SetValueAt("004010","GS:VersionReleaseIndustryIdenti", "set","")
// New TransactionSet Set target.FunctionalGroups(1).TransactionSets(1) = ##class(Ens.X12.FunctionSet).X12NewTransactionSet(target.FunctionalGroups(1), lnkObj.TransactionType.Name)
Do target.FunctionalGroups(1).TransactionSets(1).SetValueAt(lnkObj.TransactionType.Name,"ST:TransactionSetIdentifierCode","set","") Do target.FunctionalGroups(1).TransactionSets(1).SetValueAt("0001","ST:TransactionSetControlNumber","set","") QUIT $$$OK

	set x12Doc.DocType = "ERP_4010:Interchange:Group"

   set errStr = ""
   if (x12Doc.%Extends("EnsLib.EDI.X12.Document"))
	 {
		   Set tSC =x12Doc.BuildMap()

		   set InterchangeCtrlNum = x12Doc.GetValueAt("ISA:InterchangeControlNumber")
		   set InterchangeSenderID = $ZSTRIP(x12Doc.GetValueAt("ISA:InterchangeSenderID"), "<>W")
		   set InterchangeReceiverID = $ZSTRIP(x12Doc.GetValueAt("ISA:InterchangeReceiverID"), "<>W")

	      /// $$$TRACE( "Parse999::: 999 for: "  _ ISA SenderID _" -> " _ ReceiverID _ ": CtrlNum: " _ InterchangeCtrlNum)
		  set individualGroup = x12Doc.getNthChild(1,2)

		  set isaGsInfo = "ACK for ISA: "  _ InterchangeSenderID _" -> " _ InterchangeReceiverID _ ": CtrlNum: " _ InterchangeCtrlNum _ ": Group CtrlNum: " _ individualGroup.GetValueAt("GS:GroupControlNumber")
		  // WRITE !, x12Doc.ElementSeparator  _", " _ x12Doc.ComponentSeparator 
		  set STRecord=individualGroup.getNthChild(1,2)
		  set transType = STRecord.GetValueAt("1:1",, .stat)

		  set STRecord.DocType = "ERP_4010:" _ transType
		  // $$$TRACE( "Parse999::: ST: " _  transType_ ", CountGet: " _ STRecord.SegCountGet() )
		  set akStr = "", ikStr = "", stNum = 0, firstAK2 = 1
		  set refTransType = ""
		  FOR ind=1:1:STRecord.SegCountGet()
		  {

			set segPath = STRecord.GetSegmentPath(ind, .stat)	
		  	set segVal = STRecord.GetValueAt(segPath,, .stat)
		  	// WRITE !, ind _". " _ segPath _"= " _ segVal

		  	if ($FIND(segVal,"AK2") = 4)
		  	{
  			  	set refTransType = $PIECE(segVal, x12Doc.ElementSeparator , 2)

			  	Do ..ItfLookup("IHC.ITF.Process.Bpl.AkTransSetlLookup", refTransType, .retVal)
			  	set stNum = $PIECE(segVal, x12Doc.ElementSeparator , 3)

				set akStr = refTransType _" (" _ retVal _"): TransactionSet CtrlNum: " _ stNum

		  	}
		  	elseif ($FIND(segVal,"IK5") = 4)
		  	{
  			  	set seg2Val = $PIECE(segVal, x12Doc.ElementSeparator , 2)
  			  	if (seg2Val '= "A")
  			  	{
				  	Do ..ItfLookup("IHC.ITF.Process.Bpl.AkCodeLookup", seg2Val, .retVal)
				  	set ik5Str = $CHAR(13) _  " => " _ retVal _  " (" _ seg2Val _")"
				  	if ($PIECE(segVal, x12Doc.ElementSeparator , 3) '= "") {
					   	set seg3Val = $PIECE(segVal, x12Doc.ElementSeparator , 3)
				  		Do ..ItfLookup("IHC.ITF.Process.Bpl.AkErrorLookup", seg3Val, .retVal)
				  		set ik5Str = ik5Str _ ": Error: "  _ retVal _" ("  _  seg3Val  _")"
				  	}	
				  	if (ikStr '= "")
				  	{
				  	   set ik5Str = ik5Str _ ": Details:" _ ikStr 
				  	}
				  	if (firstAK2 = 1)
				  	{
				  		set errStr = errStr _ isaGsInfo  _ $CHAR(13) _ akStr _" " _ ik5Str _" # "
				  		set firstAK2 = 0
				  	}
				  	else
				  	{
					  	set errStr = errStr _ $CHAR(13) _ akStr _" " _ ik5Str _" # "
				  	}		  					
  			  	}

				set akStr = "", ikStr = ""
		  	}
		  	elseif ($FIND(segVal,"IK3") = 4)
		  	{		   
		  	    set segNum = 	$PIECE(segVal, x12Doc.ElementSeparator , 3)
				set ikStr = ikStr _ $CHAR(13) _ " Loop: " _ $PIECE(segVal, x12Doc.ElementSeparator , 4) _ ": Segment Num: " _ segNum _": " _ $PIECE(segVal, x12Doc.ElementSeparator , 2)
				Do ..ItfLookup("IHC.ITF.Process.Bpl.IK3Values", $PIECE(segVal, x12Doc.ElementSeparator , 5), .retVal)


			  	set segVal = ..GetSegment(origMsg, segNum, stNum)

			  	set ikStr = ikStr _ ": " _ retVal _". Inbound " _ refTransType _ " Segment Data: " _ segVal

		  	}
		  	elseif ($FIND(segVal,"IK4") = 4)
		  	{		   	

				Do ..ItfLookup("IHC.ITF.Process.Bpl.IK4Values", $PIECE(segVal, x12Doc.ElementSeparator , 4), .retVal)
				set eleData = $PIECE(segVal, x12Doc.ElementSeparator , 5)
			  	set ikStr = ikStr _ ": Element Position: " _ $PIECE(segVal, x12Doc.ElementSeparator , 2) _ ": Error: " _ retVal _ ": Element Data: " _ $SELECT(0=$L(eleData):"<NULL>", 1: eleData)

		  	}
		  	elseif ($FIND(segVal,"AK9") = 4)
		  	{
  			  	set seg3Val = $PIECE(segVal, x12Doc.ElementSeparator , 2)
  			  	Do ..ItfLookup("IHC.ITF.Process.Bpl.AkCodeLookup", seg3Val, .retVal)
			  	set ak9Str = "Functional Group Response: " _ seg3Val _" (" _ retVal _"): # Transaction Sets: " _ $PIECE(segVal, x12Doc.ElementSeparator , 3) _ ": # Received: " _ $PIECE(segVal, x12Doc.ElementSeparator , 4) _ ": # Accept: " _ $PIECE(segVal, x12Doc.ElementSeparator , 5)
			  	if (errStr = "")
			  	{
				  	set errStr = ak9Str
			  	}

		  	}
		  }
	 }
	 return errStr _"; " _ ak9Str

