		   set ta04 = seg.GetValueAt("4") 
		   set ta05 = seg.GetValueAt("5")
		   Do ..ItfLookup("IHC.ITF.ITFCOMMON.TA1", ta05, .retVal)
		   set retStr = "Data Error: TA1 error" _ $CHAR(13) _$CHAR(10) _ retVal _  $CHAR(13) _$CHAR(10) _ "TA014:105:" _ ta04 _":" _ ta05
	   }
	   else
	   {
		set errList = ##class(%ListOfObjects).%New()

		set GSCounter = x12Doc.ChildCount
		for gsInt=1:1:GSCounter
    	{ 
        	#dim individualGroup As EnsLib.EDI.X12.Document
        	set individualGroup = x12Doc.getNthChild(gsInt,2)

			WRITE !, "# of STs: " _ individualGroup.ChildCount

		  	FOR stInd=1:1:individualGroup.ChildCount

		  	{

				set ik3Str = "", ik4Str="", errNum = 1, segNum=0, segErrCode = 0, segErrStr ="", x12Data = ""
				set errDet = ""

				set isaGsInfo = "ACK for ISA: "  _ InterchangeSenderID _" -> " _ InterchangeReceiverID _ ": CtrlNum: " _ InterchangeCtrlNum _ ": Group CtrlNum: " _ individualGroup.GetValueAt("GS:GroupControlNumber")
				$$$TRACE( isaGsInfo)

				#dim STRecord As EnsLib.EDI.X12.Document 

			  	set STRecord=individualGroup.getNthChild(stInd,2)

			  	set STRecord.DocType = "ERP_4010:999"


				  WRITE !, gsInt _". " _ stInd _ "- Parse999::: ST Segement CountGet: " _ STRecord.SegCountGet() 
				  set akStr = "", ikStr = "", stNum = 0, firstAK2 = 1, refTransType = ""
				  set refTransType = ""
				  FOR ind=1:1:STRecord.SegCountGet()
				  {
						set numRecs = numRecs + 1


						set segPath = STRecord.GetSegmentPath(ind, .stat)	
		  				set segVal = STRecord.GetValueAt(segPath,, .stat)
		  				set recType = STRecord.GetValueAt(segPath_":0")
		  				// WRITE !, segPath _": " _ segVal _", " _ recType

						if (recType = "AK2")
						{
							set msgTrans = STRecord.GetValueAt(segPath_":1")
							set stNum = $PIECE(segVal, x12Doc.ElementSeparator , 3)
							set refTransType = $PIECE(segVal, x12Doc.ElementSeparator , 2)
							WRITE !, "Ak2: " _ refTransType _", " _ stNum
						}

						if (recType = "IK3")
						{

							 if (ikStr '= "")
							 {
								 WRITE !, "IK3 - Create IHC.ITF.ITFCOMMON.X12ErrorDetails: " _ segNum
								 set errDet = ##class(IHC.ITF.ITFCOMMON.X12ErrorDetails).%New()

									Do errList.Insert(errDet)
									set errDet.stNum = stNum
									set errDet.segNum = segNum
									set errDet.x12Data = "TBD" // x12Data
									set errDet.segErrCode = segErrCode
									set errDet.segErrStr = ikStr
									set ikStr = ""
							 }
							set segNum = 	$PIECE(segVal, x12Doc.ElementSeparator , 3)
							if ($PIECE(segVal, x12Doc.ElementSeparator , 4) > 0)
							{
								set ikStr = ikStr _ $CHAR(13) _ " Loop: " _ $PIECE(segVal, x12Doc.ElementSeparator , 4) _", "
							}
							set ikStr = ikStr _ $PIECE(segVal, x12Doc.ElementSeparator , 2)
							set segErrCode = $PIECE(segVal, x12Doc.ElementSeparator , 5)
							Do ..ItfLookup("IHC.ITF.Process.Bpl.IK3Values", segErrCode, .retVal)


						  	set segVal = ..GetFullSegmentFromX12(origX12Doc, segNum, stNum)
						  	WRITE !, segNum _", " _ stNum _ ": " _ segVal

						  	set ikStr = ikStr _ ": " _ retVal // _ " Segment Data: " _ segVal
			  				WRITE !, "IK3 -" _ 	ikStr				


						}
						elseif (recType = "IK4")
						{
							WRITE !, "IK4 - Create IHC.ITF.ITFCOMMON.X12ErrorDetails: " _ segNum
							set errDet = ##class(IHC.ITF.ITFCOMMON.X12ErrorDetails).%New()

							Do errList.Insert(errDet)

							set errDet.stNum = stNum
							set errDet.segNum = segNum
							set errDet.x12Data = "TBD" // x12Data
							set errDet.segErrCode = segErrCode
							set errDet.segErrStr = ikStr

							set ik4Err = $PIECE(segVal, x12Doc.ElementSeparator , 4)
							Do ..ItfLookup("IHC.ITF.Process.Bpl.IK4Values", ik4Err, .retVal)
							set errDet.eleErrCode = ik4Err
							set errDet.eleErrStr = retVal
							set errDet.eleNum = $PIECE(segVal, x12Doc.ElementSeparator , 2)

							set errNum = errNum + 1
							set ikStr = ""
						}
						elseif (recType = "IK5")
						{
							WRITE !, "Type of errors: " _ $PIECE(segVal, x12Doc.ElementSeparator , 3)

						}

						elseif (recType = "AK9")
						{
							set seg3Val = $PIECE(segVal, x12Doc.ElementSeparator , 2)
			  			  	Do ..ItfLookup("IHC.ITF.Process.Bpl.AkCodeLookup", seg3Val, .retVal)
						  	set ak9Err = "Functional Group Response: " _ seg3Val _" (" _ retVal _"): # Transaction Sets: " _ $PIECE(segVal, x12Doc.ElementSeparator , 3) _ ": # Received: " _ $PIECE(segVal, x12Doc.ElementSeparator , 4) _ ": # Accept: " _ $PIECE(segVal, x12Doc.ElementSeparator , 5)

						}					

					}
		  		}
    		 }
		    }
		    set retStr = ak9Err

		    // Store to WF table
		    if (storeRec)
	    	{
		    	$$$TRACE( "Store error in IHC_ITF_ITFCOMMON_X12.WorkFlow")
		    	for i=1:1: errList.Count()
			  	{
				  $$$TRACE( "Segment # " _errList.GetAt(i).segNum _", " _ errList.GetAt(i).segErrStr _", Element # " _ errList.GetAt(i).eleNum _", Error: " _ errList.GetAt(i).eleErrStr _". X12= "_ errList.GetAt(i).x12Data _" ->" _ """" _ $PIECE(errList.GetAt(i).x12Data, "*", errList.GetAt(i).eleNum+1)_ """")
				  WRITE "errList: Segment # " _errList.GetAt(i).segNum _", " _ errList.GetAt(i).segErrStr _", Element # " _ errList.GetAt(i).eleNum _", Error: " _ errList.GetAt(i).eleErrStr _". X12= "_ errList.GetAt(i).x12Data _" ->" _ """" _ $PIECE(errList.GetAt(i).x12Data, "*", errList.GetAt(i).eleNum+1)_ """"
			  	}


			  set dtTm = $ZDATETIME($HOROLOG,3, 1)
			  set x12Data = x12Doc.OutputToString()

			  WRITE !, InterchangeReceiverID _", " _ InterchangeSenderID _", " _ origX12id
			  WRITE !, "msgTrans: " _ msgTrans
			  set sqlStr = "INSERT into IHC_ITF_ITFCOMMON_X12.WorkFlow " _
			  " (InterchangeReceiverID, InterchangeSenderID, TransactionType, WorkStatus, ErrorType, Error, AssignedUser, CreateDtTm,  OrigX12Id) " _
			  " values (?,?,?,?,?,?,?,?,?)"
			  #dim rset As %SQL.StatementResult
			  set rset = ##class(%SQL.Statement).%ExecDirect(, .sqlStr, InterchangeReceiverID, InterchangeSenderID, msgTrans,  "New", "Data", retStr, "System", dtTm,  origX12id)
			  $$$TRACE( "SQL code: " _ rset.%SQLCODE)
			  if (rset.%SQLCODE < 0)
			  {
				  return $$$ERROR($$$GeneralError, "SQL failed: " _ rset.%SQLCODE _"; " _ rset.%Message)
			  }

			  set id = rset.%ROWID
			  $$$TRACE( $NAMESPACE _ " - Inserted to  WorkFlow. ID: " _ id )
			  WRITE !, "WorkFlow ID: " _ id _", " _ msgTrans 
			  set obj = ##class(IHC.ITF.ITFCOMMON.X12.WorkFlow).%OpenId(id)
			  if ($IsObject(obj))
			  {
			      WRITE !, "Insert errList #" _ errList.Count() 


 				  WRITE !, errList.GetAt(i).segNum _";segErrCode " _ errList.GetAt(i).segErrCode _"; segErrStr " _  errList.GetAt(i).segErrStr _"; eleNum " _ errList.GetAt(i).eleNum _"; eleErrCode " _  errList.GetAt(i).eleErrCode

 			      WRITE !, errList.GetAt(i).eleErrStr _"; x12Data  " _ errList.GetAt(i).x12Data 

				  $$$TRACE( "Insert errList #" _ errList.Count() )

					  for i=1:1: errList.Count()
					  {
						 if ($IsObject(errList.GetAt(i)))
				  		 {
					  		 WRITE !, errList.GetAt(i).segNum
						  		set stat = obj.ErrList.Insert(errList.GetAt(i))
						  		$$$TRACE( "insert segNum: " _ errList.GetAt(i).segNum _": " _ stat)
				  		 }
						  //
					  }
					  set stat = obj.%Save()
					  $$$TRACE( " ErrList.Count: " _ obj.ErrList.Count())
					  WRITE !, "IHC.ITF.ITFCOMMON.X12.WorkFlow ErrList.Count: " _ obj.ErrList.Count() _" Save: " _ stat


				  WRITE !, "Segment # " _errList.GetAt(i).segNum _" " _ errList.GetAt(i).segErrStr _", Element # " _ errList.GetAt(i).eleNum _" " _ errList.GetAt(i).eleErrStr _". X12= "_ errList.GetAt(i).x12Data _" ->" _ """" _ $PIECE(errList.GetAt(i).x12Data, "*", errList.GetAt(i).eleNum+1)_ """"
			  }
	    	}
	    }
	    else
	    {
		    $$$TRACE( "Not EnsLib.EDI.X12.Document")
	    }



    } catch err
	{
		set retStr = x12Doc _ " Exception: code: " _ err.Code _ ",  location: " _ err.Location
	}
   return retStr

	set mylist=##class(%ListOfDataTypes).%New()

   if ( ($ISOBJECT(x12Doc)) && (x12Doc.%Extends("EnsLib.EDI.X12.Document")) )
   {
	  set sep = x12Doc.SegmentTerminator

	 	set GSnum = 1
	 	set GSCounter = x12Doc.ChildCount

  		// WRITE !,  " GS ChildCount " _ GSCounter
          set segX12Data = ""
          while ( GSnum <= GSCounter)
          { 
            #dim individualGroup As EnsLib.EDI.X12.Document = x12Doc.getNthChild(GSnum,2)
            set individualGroup.DocType = "ERP_4010:Group"

	        Do individualGroup.SetValueAt("1", "GE:1")

	        set STCounter = individualGroup.ChildCount 

	        #dim individualST As EnsLib.EDI.X12.Document
	        set STnum = 1
	        while ( STnum <= STCounter)
	        { 
	        	set individualST = individualGroup.getNthChild(STnum)
	        	set transType = individualST.GetValueAt("ST:1")
	        	set individualST.DocType = "ERP_4010:" _ transType
	        	Do individualST.BuildMap()
	        	if $$$ISERR(individualST.BuildMapStatus)
	        	{
	        		$$$LOGERROR( "BuildMapStatus: failed" )
	        		set errStr = ""
		        	Do $system.Status.DecomposeStatus(individualST.BuildMapStatus,.err,"-d")
	  				For i=1:1:err { set errStr = errStr _", " _ err(i) }
	  				Set status =  ##class(IHC.ITF.ITFCOMMON.Utility).InputDataError(process.%ConfigName,"X12 data error. " _ errStr)

	        	}
	        	else
	        	{

		        	set indX12 = x12Doc.GetValueAt("ISA") _ sep _ individualGroup.GetValueAt("GS")_ sep

		        	set indX12 = indX12 _ individualST.OutputToString()

		        	set indX12 = indX12 _  individualGroup.GetValueAt("GE")_ sep _ x12Doc.GetValueAt("IEA")_ sep

		        	do mylist.Insert(indX12)
		        	$$$TRACE(mylist.Count() _ ". Create X12 for : " _ transType)
	        	}
		        Do $INCREMENT(STnum)

          	} 
          	Do $INCREMENT(GSnum) 
          }
  }
  return mylist
